(window.TNQ=window.TNQ||[]).push({"terms":{"기업실체":{"d":"소유주와 구별해 독립된 경제 단위로 보고 재무제표를 작성하는 대상이 되는 기업입니다.","r":[]},"단기매매증권":{"d":"단기간 내 매매차익을 얻을 목적으로 취득한 유가증권입니다.","r":["매도가능증권"]},"매도가능증권":{"d":"단기매매증권이나 만기보유증권으로 분류되지 않는 지분증권 등의 유가증권입니다.","r":["단기매매증권"]},"통화대용증권":{"d":"타인발행 당좌수표나 자기앞수표처럼 즉시 현금으로 바꿀 수 있어 현금으로 처리하는 증권입니다.","r":[]},"현금성자산":{"d":"취득 당시 만기가 3개월 이내인 채무증권이나 금융상품입니다.","r":[]},"대손충당금":{"d":"수취채권의 회수 불가능한 예상액을 나타내는 평가성 항목으로 채권에서 차감해 표시합니다.","r":[]},"이동평균법":{"d":"매입할 때마다 평균단가를 새로 계산하는 방법으로 계속기록법과 짝을 이룹니다.","r":["총평균법"]},"총평균법":{"d":"기말에 한꺼번에 평균단가를 계산하는 방법으로 실지재고조사법과 짝을 이룹니다.","r":["이동평균법"]},"감가상각":{"d":"자산이 사용 가능한 때부터 감가상각대상금액을 내용연수에 걸쳐 체계적으로 배분하는 절차입니다.","r":[]},"할증발행":{"d":"액면이자율이 시장이자율보다 커서 사채를 액면금액보다 비싸게 발행하는 것입니다.","r":["할인발행"]},"할인발행":{"d":"시장이자율이 액면이자율보다 커서 사채를 액면금액보다 싸게 발행하는 것입니다.","r":["할증발행"]},"선수수익":{"d":"아직 제공하지 않은 용역에 대해 미리 받은 수익으로 부채로 처리합니다.","r":["선급비용"]},"선급비용":{"d":"아직 제공받지 않은 용역에 대해 미리 지급한 비용으로 자산으로 처리합니다.","r":["선수수익"]},"회계추정의 변경":{"d":"추정에 필요한 정보가 바뀌어 대손율이나 내용연수 등을 고치는 일로 전진적으로 처리합니다.","r":[]},"오류수정":{"d":"전기 이전 재무제표에 포함된 회계적 오류를 당기에 발견하여 수정하는 것입니다.","r":[]},"진행기준":{"d":"거래의 진행률에 따라 수익을 인식하는 방법입니다.","r":[]}},"notes":{"감가상각대상금액은 내용연수에 걸쳐 합리적이고 체계적인 방법으로 배분":"상각 대상 금액을 내용연수 안에서 합리적이고 체계적으로 나눠 비용으로 삼습니다.","거래와 관련하여 발생했거나 발생할 원가를 신뢰성 있게 측정할 수 있음":"거래에 든 원가를 믿을 만하게 측정할 수 있어야 합니다.","건물 벽의 도장, 파손된 유리창 대체, 일반적인 소액 수선비":"건물 벽 도장, 깨진 유리창 교체, 소액 수선비가 수익적 지출의 예입니다.","건물을 신축하기 위하여 사용 중인 기존 건물을 철거하는 경우 그 건물의 장부금액은 제거하여 처분손실로 반영하고, 철거비용은 전액 당기비용으로 처리":"건물을 새로 지으려 헌 기존 건물은 장부금액을 없애 처분손실로 반영하고 철거비는 전액 당기비용입니다.","결산 때 다음 연도분 9개월 180,000원을 선급비용(자산)으로 옮김":"보험료 중 다음 연도에 해당하는 180,000원은 결산 때 선급비용 자산으로 바꿉니다.","고객이 구매의사를 표시하기 전까지 판매자의 재고":"시송품은 고객이 구매 의사를 밝히기 전까지는 판매자의 재고입니다.","과거 거래의 결과로 현재 의무가 존재":"충당부채는 과거 거래의 결과로 현재 의무가 있어야 인식합니다.","과거사건에 의해 인식하기 위해서는 그 사건이 기업의 미래행위와 독립적이어야 함":"인식하려면 그 사건이 기업의 미래 행위와 독립적이어야 합니다.","광고대행사로부터 광고대행용역을 제공받고 수수료로 10,000,000원을 지급":"광고대행용역 수수료로 10,000,000원을 지급한 거래입니다.","구입원가 또는 제작원가 및 경영진이 의도하는 방식으로 자산을 가동하는 데 필요한 장소와 상태에 이르게 하는 데 직접 관련되는 원가":"유형자산 원가는 구입·제작원가에 의도한 방식으로 가동할 장소와 상태에 이르게 하는 직접 관련 원가를 더한 것입니다.","금액은 현재의무를 이행하는 데 소요되는 지출에 대한 보고기간 말 현재 최선의 추정치":"금액은 의무 이행에 드는 지출에 대한 보고기간 말 현재의 최선의 추정치로 잽니다.","기말재고가 최근 매입단가로 남아 시가에 가깝지만, 오래된 원가가 매출원가가 되어 수익·비용 대응이 떨어짐":"선입선출법은 기말재고가 최근 단가라 시가에 가깝지만 오래된 원가가 매출원가가 되어 수익·비용 대응이 약합니다.","기말 채권잔액에 대손추정률을 곱하여 산정":"대손예상액은 기말 채권잔액에 대손추정률을 곱해 구합니다.","기업실체를 중심으로 하여 기업실체의 경제적 현상을 재무제표에 보고해야 함":"재무제표는 소유주가 아닌 기업실체를 중심에 두고 그 경제적 현상을 보고합니다.","기업실체의 지속적인 경제적 활동을 인위적으로 일정 기간 단위로 분할하여 각 기간마다 경영자의 수탁책임을 보고":"지속되는 활동을 인위적으로 기간 단위로 나눠 기간마다 경영자의 수탁책임을 보고합니다.","기업이 계속적으로 존재하지 않을 것이라는 반증이 없는 한, 기업실체의 본래 목적을 달성하기 위하여 계속적으로 존재":"기업이 없어지리라는 반증이 없으면 본래 목적을 이룰 때까지 계속 존재한다고 가정합니다.","기업이 보유하고 있는 자산과 부채, 그리고 자본에 대한 정보":"그 정보는 자산, 부채, 자본의 세 가지로 이루어집니다.","단기매매증권과 매도가능증권으로 분류할 수 있으나, 만기보유증권으로 분류할 수 없음":"지분증권은 단기매매증권이나 매도가능증권이 될 수 있지만 만기보유증권은 될 수 없습니다.","단기매매증권이 시장성을 상실한 경우에는 매도가능증권으로 분류하여야 함":"시장성을 잃은 단기매매증권은 매도가능증권으로 바꿔 분류해야 합니다.","당기에 발견한 전기 또는 그 이전 기간의 오류 중 중대한 오류가 아닌 경우 영업외손익 중 전기오류수정손익으로 보고":"중대하지 않은 전기 오류는 영업외손익의 전기오류수정손익으로 보고합니다.","대손의 추정, 재고자산의 진부화 여부에 대한 판단과 평가, 감가상각자산의 내용연수 추정 등":"회계추정의 예는 대손 추정, 재고자산 진부화 판단·평가, 감가상각자산의 내용연수 추정입니다.","대손추산액에서 기존 대손충당금 잔액을 뺀 금액을 대손상각비로 계상":"대손충당금은 필요한 총액과 이미 있는 잔액의 차이만큼만 보충해 대손상각비로 잡습니다.","대손충당금 잔액이 있으면 먼저 상계":"실제 대손이 나면 대손충당금 잔액이 있는 만큼 먼저 상계합니다.","도난·파손 같은 감모수량을 파악할 수 있음":"그래서 도난이나 파손으로 줄어든 감모수량을 파악할 수 있습니다.","매기 동일한 회계정책을 사용하면 비교가능성이 증대되어 재무제표의 유용성이 향상":"정책을 해마다 같게 쓰면 비교가능성이 커져 재무제표의 유용성이 올라갑니다.","매기 동일한 회계추정을 사용하면 비교가능성이 증대되어 재무제표의 유용성이 향상":"추정을 해마다 같게 쓰면 비교가능성이 커져 재무제표의 유용성이 올라갑니다.","무형자산 창출을 위한 내부 프로젝트를 연구단계와 개발단계로 구분할 수 없는 경우 그 프로젝트에서 발생한 지출은 모두 연구단계에서 발생한 것으로 봄":"연구와 개발 단계를 가를 수 없으면 그 프로젝트 지출 전부를 연구단계 지출로 봅니다.","물가가 오르고 기말재고 수량이 기초 이상이면 기말재고와 순이익이 가장 작음":"같은 조건에서 후입선출법은 기말재고와 순이익이 가장 작게 나옵니다.","물가가 오르고 기말재고 수량이 기초 이상이면 기말재고와 순이익이 가장 큼":"물가가 오르는 때에는 선입선출법이 기말재고와 순이익을 가장 크게 만듭니다.","미결산항목이라 결산 때까지 여비교통비 등 적절한 계정으로 대체해 최종 재무제표에 남지 않게 함":"가지급금은 미결산항목이라 결산 때까지 여비교통비 같은 적절한 계정으로 바꿔 최종 재무제표에 남기지 않습니다.","미사용액을 소모품(자산)으로 옮김":"쓰고 남은 소모품은 비용에서 빼서 자산으로 옮깁니다.","발생한 비용의 범위 내에서 회수 가능한 금액을 수익으로 인식":"성과를 추정할 수 없으면 발생한 비용 범위 안에서 회수 가능한 금액만 수익으로 인식합니다.","배당액을 이익잉여금에서 차감":"현금 배당을 하면 배당액만큼 이익잉여금이 줄어듭니다.","변동이 없으며 주주 입장에서는 주식 수 및 단가만 조정":"발행 회사의 순자산은 그대로이고 주주는 주식 수와 단가만 조정합니다.","보고기간 말마다 그 잔액을 검토하고, 보고기간 말 현재 최선의 추정치를 반영하여 증감조정":"충당부채 잔액은 보고기간 말마다 검토해 최선의 추정치로 늘리거나 줄입니다.","보통주 10,000주를 주당 11,000원(액면가액 5,000원)에 증자":"액면가 5,000원인 보통주 10,000주를 11,000원씩 받고 발행하는 증자 사례입니다.","본래의 용도를 변경하기 위한 지출":"본래 용도를 바꾸려는 지출도 자본적 지출에 속합니다.","사업에 사용하던 차량을 10,000,000원(장부가액 15,000,000원)에 매각":"사용하던 차량을 장부가액 15,000,000원인데 10,000,000원에 매각한 거래입니다.","사채할증발행차금은 사채의 액면금액에서 가산하는 형식으로 표시":"사채할증발행차금은 액면금액에 더하는 형식으로 표시합니다.","상각대상 금액은 그 자산의 추정 내용연수 동안 체계적인 방법에 의하여 비용으로 배분":"무형자산의 상각대상 금액은 추정 내용연수 동안 체계적으로 비용에 나눠 배분합니다.","상법 규정에 따라 자본금의 1/2에 달할 때까지 금전에 의한 이익배당액의 1/10 이상의 금액을 적립":"이익준비금은 상법상 자본금의 1/2에 이를 때까지 금전 배당액의 1/10 이상씩 적립합니다.","상품의 취득원가는 매입가액에 매입운임 등 취득부대비용을 더하고 매입환출·에누리·할인을 뺀 금액":"사 올 때 든 운임 같은 비용은 더하고 반품·에누리·할인은 빼서 취득원가를 정합니다.","새로운 상품과 서비스를 소개하는 데 소요되는 원가(예 : 광고 및 판촉활동과 관련된 원가)는 유형자산의 원가를 구성하지 않음":"새 상품을 소개하는 광고·판촉 원가는 유형자산 원가가 되지 못합니다.","선수수익 50,000원을 계상해 임대료에서 뺌":"임대료를 전부 수익으로 잡았으니 다음 연도에 해당하는 부분은 50,000원을 선수수익으로 돌립니다.","선적지 인도조건이면 구매자의 재고에, 도착지 인도조건이면 판매자의 재고에 포함":"미착품은 선적지 인도면 사는 쪽 재고, 도착지 인도면 파는 쪽 재고로 갈립니다.","수취채권의 평가성 항목으로서 수취채권에서 차감하는 형식으로 표시":"대손충당금은 평가성 항목이라 수취채권에서 빼는 형식으로 표시합니다.","수탁자가 팔기 전까지 위탁자의 재고":"적송품은 수탁자가 팔기 전까지는 위탁자의 재고로 둡니다.","신뢰성 있게 측정할 수 있을 것":"진행률도 믿을 만하게 측정할 수 있어야 합니다.","신뢰성 있게 측정할 수 있음":"수익 금액을 믿을 만하게 측정할 수 있어야 합니다.","액면이자율보다 시장이자율이 큰 경우":"시장이자율이 액면이자율보다 크면 액면보다 싸게 파는 할인발행이 됩니다.","액면이자율이 시장이자율보다 큰 경우 · 액면이자율이 유효이자율보다 큰 경우 발행가액이 할증":"액면이자율이 시장·유효이자율보다 크면 발행가액이 액면보다 높은 할증발행이 됩니다.","우표와 수입인지는 현금및현금성자산이라고 볼 수 없음 · 수입인지는 비용으로 처리":"우표와 수입인지는 현금성자산이 아니고 수입인지는 비용으로 처리합니다.","유동성에 따라 유동부채와 비유동부채로 구분":"부채는 유동성을 기준으로 유동부채와 비유동부채로 나눕니다.","유상증자 시 주식이 할인발행된 경우 자본조정으로 계상":"유상증자에서 액면 아래로 팔면 그 차이는 자본조정으로 계상합니다.","유형자산의 인식기준을 충족하는 경우":"자본적 지출은 유형자산 인식기준을 충족하는 지출입니다.","유효이자는 만기까지 매년 증가":"할인발행에서는 유효이자가 만기까지 해마다 늘어납니다.","의무를 이행하기 위해 자원이 유출될 가능성이 매우 높음":"자원이 유출될 가능성이 매우 높아야 인식할 수 있습니다.","이미 발생한 원가 및 거래의 완료를 위하여 투입하여야 할 원가를 신뢰성 있게 측정할 수 있을 것":"이미 쓴 원가와 거래 완료까지 투입할 원가를 믿을 만하게 측정할 수 있어야 합니다.","이미 발생한 원가와 그 거래를 완료하기 위해 추가로 발생할 것으로 추정되는 원가의 합계액이 총수익을 초과하는 경우에는 그 초과액과 이미 인식한 이익의 합계액을 전액 당기손실로 인식":"총수익보다 원가 합계가 크면 초과액과 이미 인식한 이익을 합쳐 전액 당기손실로 인식합니다.","인식기준을 충족하지 못한 경우":"수익적 지출은 인식기준에 못 미치는 지출입니다.","일정시점 현재 기업이 보유하고 있는 경제적 자원에 대한 정보":"재무상태표는 어느 한 시점에 기업이 가진 경제적 자원을 보여 줍니다.","자본금, 자본잉여금, 자본조정, 기타포괄손익누계액 및 이익잉여금(결손금)으로 구분":"자본은 주주가 낸 돈과 쌓인 이익 등을 다섯 항목, 곧 자본금·자본잉여금·자본조정·기타포괄손익누계액·이익잉여금(결손금)으로 나눠 적습니다.","자산과 부채는 유동성이 큰 항목부터 배열하는 것을 원칙으로 함":"자산과 부채는 유동성이 큰 항목을 먼저 늘어놓는 것이 원칙입니다.","자산이 사용 가능한 때부터 시작":"감가상각은 자산이 쓸 수 있게 된 때부터 시작합니다.","장부 수량과 실사 수량을 함께 보는 방법":"혼합법은 장부 수량과 실사 수량을 같이 보는 방법입니다.","재무제표의 신뢰성을 크게 해칠 수 있는 오류":"중대한 오류는 재무제표의 신뢰성을 크게 해칠 수 있는 오류입니다.","전기 또는 그 이전의 재무제표에 포함된 회계적 오류를 당기에 발견하여 수정하는 것":"오류수정은 전기 이전 재무제표의 회계 오류를 당기에 발견해 고치는 것입니다.","전진적으로 처리하여 그 효과를 당기와 당기 이후의 기간에 반영":"추정 변경은 전진적으로 처리해 효과를 당기와 이후 기간에 반영합니다.","정상적인 영업과정에서 판매를 목적으로 하는 자산":"재고자산은 정상 영업과정에서 팔려는 목적으로 가진 자산입니다.","제조와 관련된 무형자산의 상각비는 제조원가에 포함":"제조에 쓰인 무형자산의 상각비는 판매관리비가 아니라 제조원가로 흘러갑니다.","주된 영업활동인 상품매매는 2분법으로 처리해, 판매 때 매출만 인식하고 매출원가는 기말 결산에 한꺼번에 인식":"2분법에서는 판매할 때 매출만 인식하고 매출원가는 기말 결산에서 한꺼번에 인식합니다.","주로 단기간 내 매매차익을 목적으로 취득한 유가증권":"단기매매증권은 짧은 기간에 매매차익을 얻으려고 산 유가증권입니다.","주식소각 대가를 주주에게 지급하지 않으므로 형식적 감자에 해당":"대가를 주주에게 주지 않고 주식을 없애므로 무상감자는 형식적 감자입니다.","주식수만 증가할 뿐 자본금에 미치는 영향은 발생하지 않음":"주식분할은 주식수만 늘고 자본금에는 영향이 없습니다.","주주의 납입자본에 기업활동을 통하여 획득하고 기업의 활동을 위해 유보된 금액을 가산하고, 기업활동으로 인한 손실 및 소유자에 대한 배당으로 인한 주주지분 감소액을 차감한 잔액":"자본은 주주의 납입자본에 유보된 이익을 더하고 손실과 배당으로 줄어든 주주지분을 뺀 잔액입니다.","증권의 종류에 따라 지분증권과 채무증권으로 분류":"증권은 종류에 따라 지분증권과 채무증권으로 나뉩니다.","직원가불금은 단기대여금이므로 현금및현금성자산이라고 볼 수 없음":"직원에게 미리 준 가불금은 단기대여금이라 현금및현금성자산에서 빠집니다.","진행기준에 따라 수익을 인식":"주문 개발 소프트웨어의 수수료는 진행기준으로 수익을 인식합니다.","짝을 이루는 평균법은 이동평균법":"계속기록법과 짝이 되는 평균법은 이동평균법입니다.","짝을 이루는 평균법은 총평균법":"실지재고조사법과 짝이 되는 평균법은 총평균법입니다.","총매출액에서 매출환입, 매출에누리, 매출할인을 차감한 금액":"순매출액은 총매출액에서 매출환입·매출에누리·매출할인을 뺀 금액입니다.","최초의 인식시점에서 의도한 목적과 용도로만 사용해야 함":"충당부채는 처음 인식할 때 의도한 목적과 용도로만 써야 합니다.","충당부채를 발생시킨 사건과 밀접하게 관련된 자산의 예상되는 처분차익은 충당부채 금액의 측정에 고려하지 아니함":"관련 자산의 예상 처분차익은 충당부채 금액을 측정할 때 고려하지 않습니다.","타인발행 당좌수표와 자기앞수표는 통화대용증권이므로 현금으로 처리":"당좌수표와 자기앞수표는 곧 현금으로 바꿀 수 있는 통화대용증권이어서 현금에 넣습니다.","판매 목적 보유 자산, 생산과정 중인 자산, 생산에 투입할 자산이며, 부동산매매업자가 파는 토지도 재고자산":"파는 물건, 만드는 중인 물건, 만들 때 쓸 재료가 모두 재고자산이고 부동산매매업자의 토지도 포함됩니다.","판매비와관리비가 아닌 영업외비용인 기타의대손상각비로 처리":"미수금과 대여금의 대손은 판매비와관리비가 아니라 영업외비용인 기타의대손상각비입니다.","판매비와관리비인 운반비로 처리":"상품을 팔면서 낸 운송료는 판매비와관리비인 운반비로 처리합니다.","판매자는 판매한 재화에 대하여 소유권이 있을 때 통상적으로 행사하는 정도의 관리나 효과적인 통제를 할 수 없음":"판매자가 소유권자 수준의 관리나 효과적 통제를 더는 하지 않아야 합니다.","현금성자산은 채무증권이나 금융상품 중 취득 당시 만기가 3개월 이내인 것이고, 3개월 판단의 기준일은 취득일":"현금성자산은 취득 당시 만기가 3개월 이내인 것이며 기준일은 취득일입니다.","회계변경의 효과를 회계정책의 변경효과와 회계추정의 변경효과로 구분하는 것이 불가능한 경우 회계추정의 변경으로 봄":"두 변경 효과를 가를 수 없다면 회계추정의 변경으로 봅니다.","회계정보이용자들이 기업의 유동성, 재무적 탄력성, 수익성과 위험을 평가하는 데 정보를 제공":"이용자는 이 표로 유동성, 재무적 탄력성, 수익성과 위험을 평가합니다.","효과는 당해 회계연도 개시일부터 적용":"효과는 변경이 있는 그 회계연도 개시일부터 적용합니다.","효과는 변경 전 사용하였던 손익계산서 항목과 동일한 항목으로 처리":"효과는 변경 전에 쓰던 손익계산서 항목과 같은 항목으로 처리합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
